			}, ['uploadedpicture', 'picture']);
			return uploadedImage;
		} finally {
			await file.delete(picture.path);
		}
	};

	const imageExtensions = ['png', 'jpeg', 'jpg', 'bmp'];

	function localProfilePath(url) {
		const prefix = `${nconf.get('relative_path') || ''}/assets/uploads/profile/`;
		if (typeof url !== 'string' || !url.startsWith(prefix)) {
			return false;
		}
		const filename = url.slice(prefix.length);
		if (!filename || filename === '.' || filename === '..' || path.basename(filename) !== filename || !/^[^?#\\/]+$/.test(filename)) {
			return false;
		}
		return path.join(nconf.get('upload_path'), 'profile', filename);
	}

	async function profileImagePaths(uid, type) {
		if (!Number.isSafeInteger(Number(uid)) || Number(uid) <= 0) {
			throw new Error('[[error:invalid-uid]]');
		}
		const folder = path.join(nconf.get('upload_path'), 'profile');
		let names;
		try {
			names = await fs.promises.readdir(folder);
		} catch (err) {
			if (err.code === 'ENOENT') return [];
			throw err;
		}
		const pattern = new RegExp(`^${uid}-profile${type}(?:-[0-9]+)?\\.(?:${imageExtensions.join('|')})$`, 'i');
		return names.filter(name => pattern.test(name)).map(name => path.join(folder, name));
	}

	async function removeLocalFiles(paths) {
		await Promise.all([...new Set(paths.filter(Boolean))].map(async (filename) => {
			try {
				await fs.promises.unlink(filename);
			} catch (err) {
				if (err.code !== 'ENOENT') throw err;
			}
		}));
	}

	async function deleteCurrentPicture(uid, field) {
		if (meta.config['profile:keepAllUserImages']) return;
		await removeLocalFiles([localProfilePath(await User.getUserField(uid, field))]);
	}

	User.getLocalCoverPath = async function (uid) {
		const url = await User.getUserField(uid, 'cover:url');
		const local = localProfilePath(url);
		if (!local) return false;
		const paths = await profileImagePaths(uid, 'cover');
		return paths.includes(local) ? local : (paths[0] || false);
	};

	User.getLocalAvatarPath = async function (uid) {
		const url = await User.getUserField(uid, 'uploadedpicture');
		const local = localProfilePath(url);
		if (!local) return false;
		const paths = await profileImagePaths(uid, 'avatar');
		return paths.includes(local) ? local : (paths[0] || false);
	};

	User.removeProfileImage = async function (uid) {
		const previous = await User.getUserFields(uid, ['uploadedpicture', 'picture']);
		await removeLocalFiles([
			localProfilePath(previous.uploadedpicture),
			...await profileImagePaths(uid, 'avatar'),
		]);
		await User.setUserFields(uid, {
			uploadedpicture: '',
			picture: previous.uploadedpicture === previous.picture ? '' : previous.picture,
		});
		return previous;
	};

	function validateUpload(data, maxSize, allowedTypes) {
		if (!data.imageData) {
			throw new Error('[[error:invalid-data]]');
		}

	Groups.removeCover = async function (data) {
		const key = `group:${data.groupName}`;
		const fields = ['cover:url', 'cover:thumb:url', 'cover:position'];
		const covers = await db.getObjectFields(key, fields);
		const prefix = `${nconf.get('relative_path') || ''}/assets/uploads/files/`;
		await Promise.all(['cover:url', 'cover:thumb:url'].map(async (field) => {
			const url = covers[field];
			if (typeof url !== 'string' || !url.startsWith(prefix)) return;
			const filename = url.slice(prefix.length);
			if (!filename || filename === '.' || filename === '..' || path.basename(filename) !== filename || !/^[^?#\\/]+$/.test(filename)) return;
			try {
				await fs.promises.unlink(path.join(nconf.get('upload_path'), 'files', filename));
			} catch (err) {
				if (err.code !== 'ENOENT') throw err;
			}
		}));
		await db.deleteObjectFields(key, fields);
	};
};

